SELECT product_number,item_name,string_agg(distinct category_name,' | ') categories,min(trading_date),max(trading_date),count(*) FROM canonical_sale_item WHERE superseded_at IS NULL AND (product_number IN('20161229','21162117','23673809','19989720','22857471','12027390','23643649','23562304','17878130','12027397','17914368','22510826','20824947') OR lower(item_name) ~ '(gnocchi.*pumpkin|stargazer|dill aioli)') GROUP BY 1,2 ORDER BY 1,2;
SELECT d.recipe_id,d.name,s.description,s.stock_id FROM canonical_recipe_definition d JOIN canonical_recipe_definition_stocks s ON d.id=s.snapshot_id WHERE d.superseded_at IS NULL AND d.recipe_id IN(198,570,52,316,175,410,185,330,632,666) ORDER BY 1,s.line_order;
SELECT name,category,source_system,source_product_id,sku FROM source_product WHERE superseded_at IS NULL AND lower(name) ~ '(gnocchi|stargazer|dill aioli)';
